-- STUDYROOM POSTGRESQL DRAFT — design only.
-- This file is NOT wired into the application and must not be run as a migration yet.
-- IDs use GENERATED BY DEFAULT so an importer can preserve JSON IDs, then reseed sequences.

BEGIN;

CREATE TABLE IF NOT EXISTS users (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name TEXT NOT NULL,
  email TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('student', 'teacher', 'admin')),
  sexe TEXT,
  matricule TEXT,
  promotion TEXT,
  filiere TEXT,
  faculte TEXT,
  classe TEXT,
  specialite TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  deleted_at TIMESTAMPTZ,
  token_version INTEGER NOT NULL DEFAULT 0 CHECK (token_version >= 0),
  created_at TIMESTAMPTZ
);

CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower_uq ON users (lower(email));
CREATE INDEX IF NOT EXISTS users_role_active_idx ON users (role, is_active) WHERE deleted_at IS NULL;
-- Matricule is deliberately not unique: historical JSON records can reuse it.

CREATE TABLE IF NOT EXISTS assignments (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title TEXT NOT NULL,
  subject TEXT,
  instructions TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('interrogation', 'devoir', 'examen')),
  faculty TEXT NOT NULL,
  promotion TEXT NOT NULL,
  teacher_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  start_at TIMESTAMPTZ NOT NULL,
  end_at TIMESTAMPTZ NOT NULL,
  duration_minutes INTEGER NOT NULL CHECK (duration_minutes > 0),
  status TEXT NOT NULL,
  created_at TIMESTAMPTZ,
  deleted_at TIMESTAMPTZ,
  CHECK (end_at > start_at)
);

CREATE INDEX IF NOT EXISTS assignments_teacher_idx ON assignments (teacher_id, status);
CREATE INDEX IF NOT EXISTS assignments_target_idx ON assignments (status, faculty, promotion, start_at, end_at)
  WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS assignment_questions (
  assignment_id INTEGER NOT NULL REFERENCES assignments(id) ON DELETE CASCADE,
  question_id INTEGER NOT NULL,
  position INTEGER NOT NULL CHECK (position > 0),
  question_type TEXT NOT NULL CHECK (question_type IN ('qcm', 'vrai_faux', 'ouverte')),
  question_text TEXT NOT NULL,
  options JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(options) = 'array'),
  correct_answer TEXT NOT NULL,
  expected_answer TEXT NOT NULL DEFAULT '',
  points NUMERIC(6,2) NOT NULL CHECK (points > 0),
  PRIMARY KEY (assignment_id, question_id),
  UNIQUE (assignment_id, position)
);

CREATE TABLE IF NOT EXISTS submissions (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  assignment_id INTEGER NOT NULL REFERENCES assignments(id) ON DELETE RESTRICT,
  student_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  started_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  submitted_at TIMESTAMPTZ,
  status TEXT NOT NULL CHECK (status IN ('in_progress', 'submitted', 'expired')),
  answers JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(answers) = 'array'),
  UNIQUE (assignment_id, student_id)
);

CREATE INDEX IF NOT EXISTS submissions_student_status_idx ON submissions (student_id, status);
CREATE INDEX IF NOT EXISTS submissions_assignment_status_idx ON submissions (assignment_id, status);

CREATE TABLE IF NOT EXISTS results (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  assignment_id INTEGER REFERENCES assignments(id) ON DELETE SET NULL,
  student_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  submission_id INTEGER UNIQUE REFERENCES submissions(id) ON DELETE SET NULL,
  -- Snapshot columns retain manually entered or otherwise unlinked historical results.
  full_name TEXT NOT NULL,
  email TEXT NOT NULL,
  matricule TEXT,
  sexe TEXT,
  faculte TEXT,
  promotion TEXT,
  exam_title TEXT NOT NULL,
  subject TEXT,
  assignment_type TEXT,
  score NUMERIC(8,2) NOT NULL CHECK (score >= 0),
  max_score NUMERIC(8,2) NOT NULL CHECK (max_score >= 0 AND score <= max_score),
  percentage NUMERIC(5,2) NOT NULL CHECK (percentage BETWEEN 0 AND 100),
  status TEXT NOT NULL,
  occurred_at TIMESTAMPTZ NOT NULL,
  details JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(details) = 'array')
);

CREATE INDEX IF NOT EXISTS results_student_date_idx ON results (student_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS results_assignment_date_idx ON results (assignment_id, occurred_at DESC);
-- Do not enforce one result per assignment/student here: the current manual
-- POST /api/results route can create multiple results without a submission link.

CREATE TABLE IF NOT EXISTS notifications (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  occurred_at TIMESTAMPTZ NOT NULL,
  is_read BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE INDEX IF NOT EXISTS notifications_user_unread_date_idx
  ON notifications (user_id, occurred_at DESC) WHERE is_read = FALSE;

CREATE TABLE IF NOT EXISTS promo_codes (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code TEXT NOT NULL,
  label TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  is_active BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  CHECK (code = upper(code) AND code ~ '^[A-Z0-9_-]{4,32}$')
);

CREATE UNIQUE INDEX IF NOT EXISTS promo_codes_code_upper_uq ON promo_codes (upper(code));
CREATE INDEX IF NOT EXISTS promo_codes_active_idx ON promo_codes (is_active);

CREATE TABLE IF NOT EXISTS password_reset_tokens (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash CHAR(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[a-f0-9]{64}$'),
  created_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  used_at TIMESTAMPTZ,
  consumed_by TEXT,
  CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS password_reset_user_expiry_idx ON password_reset_tokens (user_id, expires_at DESC);

-- Written only by a future importer, inside its data-import transaction.
-- Same-file replays are no-ops; a changed source checksum requires an explicit review.
CREATE TABLE IF NOT EXISTS json_import_manifest (
  source_file TEXT PRIMARY KEY,
  source_sha256 CHAR(64) NOT NULL CHECK (source_sha256 ~ '^[a-f0-9]{64}$'),
  row_count BIGINT NOT NULL CHECK (row_count >= 0),
  imported_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMIT;
